import json
s=json.load(open('schema.json'))
d=s.get('definitions') or s.get('$defs')
for k in ['DiscoverRequest','DiscoverResult','DiscoverResultResponse','ServerCapabilities','CacheableResult','Result','RequestParams','RequestMetaObject','Implementation','BaseMetadata','UnsupportedProtocolVersionError']:
    if k in d:
        print('=== '+k)
        print(json.dumps(d[k],indent=2)[:3000])
    else:
        print('=== '+k+' MISSING')

